1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { familyFor } from "./game-config";
7	import { modLoad, modCompat, type ModLoad, type Compat } from "./mod-load";
8	import { installSupport } from "./mod-install-support";
9	
10	/**
11	 * Mod-manager actions.
12	 *
13	 * Customers browse the per-game mod/plugin CATALOG (GameMod) and one-click
14	 * install/uninstall onto their server. Each change writes the desired state to a
15	 * `ServerMod` row (INSTALLING / REMOVING) and enqueues a single GAME_MOD_SYNC job
16	 * that reconciles the server to that state — the same state-driven pattern as
17	 * GAME_CONFIG (worker reads the DB, no per-op payloads to trust).
18	 *
19	 * Ownership + the "one in-flight job per server" invariant mirror
20	 * lib/actions-game-config.ts.
21	 */
22	
23	async function ownedServer(serverId: string) {
24	  const user = await requireUser();
25	  const server = await db.server.findUnique({
26	    where: { id: serverId },
27	    include: { osTemplate: true, gamePlan: true },
28	  });
29	  if (!server) throw new Error("Not found");
30	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
31	  return { user, server };
32	}
33	
34	async function hasInflightJob(serverId: string): Promise<boolean> {
35	  const pending = await db.job.count({
36	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
37	  });
38	  return pending > 0;
39	}
40	
41	export type CatalogMod = {
42	  id: string;
43	  name: string;
44	  slug: string;
45	  category: string;
46	  source: string;
47	  url: string | null;
48	  description: string | null;
49	  iconUrl: string | null;
50	  paid: boolean;
51	  featured: boolean;
52	  appliesToVariant: string | null;
53	  /** install state for THIS server: null = not installed. */
54	  status: string | null;
55	  error: string | null;
56	  /* ── verified upstream facts (scripts/verify-gamemods.ts) ──────────────
57	     Every one of these is read from the mod's own source. Where a source
58	     doesn't publish something it stays null/empty and the panel says so,
59	     rather than filling the gap with a plausible-looking number. */
60	  downloads: number | null;
61	  fileBytes: number | null;
62	  dependencyCount: number;
63	  impact: string;
64	  impactNote: string | null;
65	  verified: boolean;
66	  compat: Compat;
67	  /** Null when one-click install works; the reason it doesn't, otherwise. */
68	  manualInstall: string | null;
69	};
70	
71	export type ModsView = {
72	  family: string;
73	  variant: string | null;
74	  /** catalog entries (compatible with the server's variant), grouped by category. */
75	  categories: { category: string; mods: CatalogMod[] }[];
76	  installedCount: number;
77	  busy: boolean;
78	  /** The version this server is pinned to, when its game has one. */
79	  gameVersion: string | null;
80	  /** What the installed set is asking of this server. */
81	  load: ModLoad;
82	};
83	
84	/**
85	 * Load the mod catalog for an owned game server, annotated with each mod's
86	 * install state on this server. Only mods for the server's game family and
87	 * compatible with its selected variant are returned.
88	 */
89	export async function getServerMods(
90	  serverId: string
91	): Promise<{ error?: string; view?: ModsView }> {
92	  const { server } = await ownedServer(serverId);
93	  const family = familyFor(server);
94	  if (!family) return { error: "This server doesn't support mods." };
95	
96	  const variant = server.gameVariant ?? null;
97	  /* The pinned game version lives in the per-family config blob under VERSION
98	     (a docker env var for the Minecraft images, not a server.properties key —
99	     see lib/game-config.ts). Families without one simply have no verdict. */
100	  const cfg = (server.gameConfig ?? null) as Record<string, unknown> | null;
101	  const rawVersion = cfg && typeof cfg.VERSION === "string" ? cfg.VERSION.trim() : "";
102	  // "LATEST"/"SNAPSHOT" name a moving target, not a version we can match against.
103	  const gameVersion = rawVersion && !/^(latest|snapshot)$/i.test(rawVersion) ? rawVersion : null;
104	
105	  const [catalog, installed, busy] = await Promise.all([
106	    db.gameMod.findMany({
107	      // A project that no longer resolves upstream would fail on install, so it
108	      // is not offered — see scripts/verify-gamemods.ts.
109	      where: { gameFamily: family, active: true, upstreamOk: true },
110	      orderBy: [{ featured: "desc" }, { popularity: "desc" }, { name: "asc" }],
111	    }),
112	    db.serverMod.findMany({ where: { serverId } }),
113	    hasInflightJob(serverId),
114	  ]);
115	
116	  const stateByMod = new Map(installed.map((m) => [m.modId, m]));
117	
118	  // Hide mods that target a different loader/variant than the server runs.
119	  const compatible = catalog.filter(
120	    (m) => !m.appliesToVariant || !variant || m.appliesToVariant === variant
121	  );
122	
123	  const byCategory = new Map<string, CatalogMod[]>();
124	  for (const m of compatible) {
125	    const st = stateByMod.get(m.id);
126	    const row: CatalogMod = {
127	      id: m.id,
128	      name: m.name,
129	      slug: m.slug,
130	      category: m.category,
131	      source: m.source,
132	      url: m.url,
133	      description: m.description,
134	      iconUrl: m.iconUrl,
135	      paid: m.paid,
136	      featured: m.featured,
137	      appliesToVariant: m.appliesToVariant,
138	      status: st?.status ?? null,
139	      error: st?.error ?? null,
140	      downloads: m.downloads,
141	      fileBytes: m.fileBytes,
142	      dependencyCount: m.dependencyCount,
143	      impact: m.impact,
144	      impactNote: m.impactNote,
145	      verified: m.verifiedAt !== null,
146	      manualInstall: (() => {
147	        const sup = installSupport(family, m.source);
148	        return sup.ok ? null : sup.message;
149	      })(),
150	      compat: modCompat(
151	        { gameVersions: m.gameVersions, loaders: m.loaders, serverSide: m.serverSide },
152	        { gameVersion, variant },
153	      ),
154	    };
155	    const arr = byCategory.get(m.category) ?? [];
156	    arr.push(row);
157	    byCategory.set(m.category, arr);
158	  }
159	
160	  const categories = [...byCategory.entries()]
161	    .map(([category, mods]) => ({ category, mods }))
162	    .sort((a, b) => a.category.localeCompare(b.category));
163	
164	  const live = installed.filter((m) => m.status === "INSTALLED" || m.status === "INSTALLING");
165	  const byId = new Map(catalog.map((m) => [m.id, m]));
166	  const load = modLoad({
167	    // The game plan is what the customer bought and what sizes the VM; the base
168	    // plan only backs it. Falling back to 0 would claim a 0 GB server, so an
169	    // unknown size means no ratio rather than a wrong one.
170	    ramMB: server.gamePlan?.ramMB ?? 0,
171	    installed: live.map((s) => {
172	      const m = byId.get(s.modId);
173	      return { name: m?.name ?? "Unknown mod", fileBytes: m?.fileBytes ?? null, impact: m?.impact ?? "light" };
174	    }),
175	  });
176	
177	  return {
178	    view: { family, variant, categories, installedCount: live.length, busy, gameVersion, load },
179	  };
180	}
181	
182	/** Queue a mod for install on an owned server. */
183	export async function installMod(
184	  serverId: string,
185	  modId: string
186	): Promise<{ error?: string; ok?: boolean }> {
187	  const { user, server } = await ownedServer(serverId);
188	  const family = familyFor(server);
189	  if (!family) return { error: "This server doesn't support mods." };
190	
191	  const mod = await db.gameMod.findUnique({ where: { id: modId } });
192	  if (!mod || !mod.active) return { error: "That mod is unavailable." };
193	  if (mod.gameFamily !== family) return { error: "That mod isn't for this game." };
194	  if (mod.appliesToVariant && server.gameVariant && mod.appliesToVariant !== server.gameVariant) {
195	    return { error: `${mod.name} needs the "${mod.appliesToVariant}" server type.` };
196	  }
197	
198	  /* Refuse here rather than queue a GAME_MOD_SYNC that can only come back
199	     "auto-install isn't wired for this game". The panel already hides the
200	     button for these, so reaching this is a stale page or a direct call — but
201	     an unrunnable job would still take the server's one in-flight slot. */
202	  const support = installSupport(family, mod.source);
203	  if (!support.ok) return { error: support.message };
204	
205	  const existing = await db.serverMod.findUnique({
206	    where: { serverId_modId: { serverId, modId } },
207	  });
208	  if (existing && (existing.status === "INSTALLED" || existing.status === "INSTALLING")) {
209	    return { error: `${mod.name} is already installed.` };
210	  }
211	
212	  if (await hasInflightJob(serverId)) {
213	    return { error: "Another operation is already in progress on this server." };
214	  }
215	
216	  await db.serverMod.upsert({
217	    where: { serverId_modId: { serverId, modId } },
218	    create: { serverId, modId, status: "INSTALLING", error: null },
219	    update: { status: "INSTALLING", error: null },
220	  });
221	  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId } });
222	  await db.auditLog.create({
223	    data: { userId: user.id, action: "gameserver.mod.install", detail: `${serverId} mod=${mod.slug}` },
224	  });
225	
226	  revalidatePath(`/dashboard/servers/${serverId}`);
227	  return { ok: true };
228	}
229	
230	/** Queue a mod for removal from an owned server. */
231	export async function uninstallMod(
232	  serverId: string,
233	  modId: string
234	): Promise<{ error?: string; ok?: boolean }> {
235	  const { user, server } = await ownedServer(serverId);
236	
237	  const existing = await db.serverMod.findUnique({
238	    where: { serverId_modId: { serverId, modId } },
239	    include: { mod: true },
240	  });
241	  if (!existing || existing.status === "REMOVED") {
242	    return { error: "That mod isn't installed." };
243	  }
244	
245	  if (await hasInflightJob(serverId)) {
246	    return { error: "Another operation is already in progress on this server." };
247	  }
248	
249	  await db.serverMod.update({
250	    where: { serverId_modId: { serverId, modId } },
251	    data: { status: "REMOVING", error: null },
252	  });
253	  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId } });
254	  await db.auditLog.create({
255	    data: { userId: user.id, action: "gameserver.mod.uninstall", detail: `${serverId} mod=${existing.mod.slug}` },
256	  });
257	
258	  void server; // ownership already enforced above
259	  revalidatePath(`/dashboard/servers/${serverId}`);
260	  return { ok: true };
261	}
