1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import { connectionTarget, serverRootPassword } from "../lib/sftp";
4	import { INSTALLABLE_FAMILIES, RESOLVABLE_SOURCES } from "../lib/mod-install-support";
5	import { Client, type ClientChannel } from "ssh2";
6	import type { Job } from "@prisma/client";
7	
8	/**
9	 * GAME_MOD_SYNC handler — reconcile a game server's installed mods to the desired
10	 * state recorded in `ServerMod` rows:
11	 *   - status INSTALLING → fetch + install the mod, then INSTALLED (or FAILED)
12	 *   - status REMOVING   → remove the mod, then delete the row (or FAILED)
13	 *
14	 * Wire into worker/index.ts handlers:  GAME_MOD_SYNC: gameModSync,
15	 *
16	 * THREE PATHS, mirroring game-config's honesty guard so we never tell a customer a
17	 * mod is installed when nothing was written to their server:
18	 *  - SANDBOX: simulate (flip INSTALLING→INSTALLED, REMOVING→REMOVED). Dev only.
19	 *  - REAL (ENABLE_REAL_GAMEMODS=1, not sandbox): install/remove over SSH via the
20	 *    per-source adapter. Where an adapter isn't implemented yet, the mod is marked
21	 *    FAILED with a clear reason — never silently "INSTALLED".
22	 *  - Neither (production, flag off): mark the queued changes FAILED with a plain
23	 *    message. A change we did NOT apply is a failure and must say so.
24	 */
25	
26	const REAL_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMEMODS === "1";
27	
28	async function notify(userId: string, title: string, body?: string, href?: string) {
29	  try {
30	    await db.notification.create({ data: { userId, title, body, href } });
31	  } catch (e) {
32	    console.error("[game-mods] notify failed", e);
33	  }
34	}
35	
36	export async function gameModSync(job: Job): Promise<void> {
37	  const serverId = job.serverId;
38	  if (!serverId) throw new Error("game mod sync: job has no serverId");
39	
40	  const server = await db.server.findUnique({
41	    where: { id: serverId },
42	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
43	  });
44	  if (!server) throw new Error(`Server ${serverId} not found`);
45	
46	  const pending = await db.serverMod.findMany({
47	    where: { serverId, status: { in: ["INSTALLING", "REMOVING"] } },
48	    include: { mod: true },
49	  });
50	  if (pending.length === 0) return;
51	
52	  const installedNames: string[] = [];
53	  const removedNames: string[] = [];
54	  const failedNames: string[] = [];
55	
56	  for (const sm of pending) {
57	    const removing = sm.status === "REMOVING";
58	    try {
59	      if (SANDBOX) {
60	        // Dev simulation — no VM mutation.
61	        if (removing) {
62	          await db.serverMod.delete({ where: { id: sm.id } });
63	          removedNames.push(sm.mod.name);
64	        } else {
65	          await db.serverMod.update({ where: { id: sm.id }, data: { status: "INSTALLED", error: null } });
66	          installedNames.push(sm.mod.name);
67	        }
68	        continue;
69	      }
70	
71	      if (!REAL_ENABLED) {
72	        // Honest failure: nothing was applied. Do NOT report success.
73	        await db.serverMod.update({
74	          where: { id: sm.id },
75	          data: {
76	            status: "FAILED",
77	            error:
78	              "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified.",
79	          },
80	        });
81	        failedNames.push(sm.mod.name);
82	        continue;
83	      }
84	
85	      // REAL path — install/remove over SSH via the per-source adapter.
86	      const modRow: ModRowFull = {
87	        gameFamily: sm.mod.gameFamily,
88	        source: sm.mod.source,
89	        sourceId: sm.mod.sourceId,
90	        slug: sm.mod.slug,
91	        name: sm.mod.name,
92	        url: sm.mod.url,
93	        variant: server.gameVariant ?? null,
94	        appliesTo: sm.mod.appliesToVariant ?? null,
95	      };
96	      const result = removing ? await removeModReal(server, modRow) : await installModReal(server, modRow);
97	
98	      if (result.ok) {
99	        if (removing) {
100	          await db.serverMod.delete({ where: { id: sm.id } });
101	          removedNames.push(sm.mod.name);
102	        } else {
103	          await db.serverMod.update({
104	            where: { id: sm.id },
105	            data: { status: "INSTALLED", version: result.version ?? null, error: null },
106	          });
107	          installedNames.push(sm.mod.name);
108	        }
109	      } else {
110	        await db.serverMod.update({
111	          where: { id: sm.id },
112	          data: { status: removing ? "INSTALLED" : "FAILED", error: result.error ?? "install failed" },
113	        });
114	        failedNames.push(sm.mod.name);
115	      }
116	    } catch (e) {
117	      const msg = e instanceof Error ? e.message : String(e);
118	      console.error(`[game-mods] ${removing ? "remove" : "install"} failed for ${sm.mod.slug}:`, e);
119	      await db.serverMod.update({
120	        where: { id: sm.id },
121	        // A failed removal stays INSTALLED (it's still there); a failed install is FAILED.
122	        data: { status: removing ? "INSTALLED" : "FAILED", error: msg },
123	      });
124	      failedNames.push(sm.mod.name);
125	    }
126	  }
127	
128	  // One summary notification for the batch.
129	  const parts: string[] = [];
130	  if (installedNames.length) parts.push(`installed ${installedNames.join(", ")}`);
131	  if (removedNames.length) parts.push(`removed ${removedNames.join(", ")}`);
132	  if (failedNames.length) parts.push(`could not apply ${failedNames.join(", ")}`);
133	  const anyOk = installedNames.length > 0 || removedNames.length > 0;
134	  const allFailed = !anyOk && failedNames.length > 0;
135	
136	  await notify(
137	    server.userId,
138	    allFailed ? `Mod changes failed on ${server.hostname}` : `Mods updated on ${server.hostname}`,
139	    parts.length ? `${parts.join("; ")}.` : "No changes were made.",
140	    `/dashboard/servers/${server.id}?tab=mods`
141	  );
142	}
143	
144	// ===========================================================================
145	// Real install/remove — per-source adapters over SSH.
146	//
147	// Approach: the worker resolves a DIRECT download URL from the source's API, then
148	// SSHes into the game VM and has the VM itself `curl` the file into the game's
149	// plugin/mod directory (deterministic filename, so uninstall is a plain rm — no
150	// per-install state to track). Sources that need auth or per-repo handling
151	// (GitHub release zips, Nexus, CurseForge key, Codefling paid) soft-fail with a
152	// clear "install manually from <url>" note rather than faking success.
153	//
154	// Supported today: modrinth + spigotmc (Minecraft), umod (Rust), thunderstore
155	// (Valheim) — which fully covers those three games' catalogs.
156	// ===========================================================================
157	
158	type ModResult = { ok: boolean; version?: string; error?: string };
159	type ModRow = {
160	  gameFamily: string;
161	  source: string;
162	  sourceId: string | null;
163	  slug: string;
164	  name: string;
165	  url: string | null;
166	};
167	type SshServer = {
168	  id: string;
169	  rootPassword: string | null;
170	  rootPasswordEnc?: string | null;
171	  sshPort: number | null;
172	  dedicatedIp?: { address: string } | null;
173	  node?: { publicIp: string } | null;
174	};
175	
176	const CONNECT_TIMEOUT_MS = 15_000;
177	const EXEC_TIMEOUT_MS = 200_000; // downloads can be large
178	
179	/** PascalCase a mod name for an Oxide/Carbon .cs filename (class-name convention). */
180	function pascal(name: string): string {
181	  const p = name.replace(/[^a-zA-Z0-9]+/g, " ").trim().split(/\s+/).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("");
182	  return p || "Plugin";
183	}
184	
185	/** Deterministic on-disk target for a mod, or null if its source isn't installable. */
186	function planTarget(mod: ModRow): { kind: "jar" | "cs" | "zip"; file?: string; folder?: string } | null {
187	  switch (mod.source) {
188	    case "modrinth":
189	    case "spigotmc":
190	      return { kind: "jar", file: `nxeon-${mod.slug}.jar` };
191	    case "umod":
192	      return { kind: "cs", file: `${pascal(mod.name)}.cs` };
193	    case "thunderstore":
194	      return { kind: "zip", folder: `nxeon-${mod.slug}` };
195	    default:
196	      return null; // github / nexus / curseforge / codefling / hangar — manual
197	  }
198	}
199	
200	/** Resolve a direct download URL from the source's API (worker-side). */
201	async function resolveUrl(mod: ModRowFull): Promise<string | null> {
202	  const id = mod.sourceId ?? "";
203	  try {
204	    switch (mod.source) {
205	      case "umod":
206	        return `https://umod.org/plugins/${id}.cs`;
207	      case "spigotmc":
208	        return `https://api.spiget.org/v2/resources/${id}/download`;
209	      case "modrinth": {
210	        const loader = modrinthLoader(mod);
211	        const q = loader ? `?loaders=["${loader}"]` : "";
212	        const res = await fetch(`https://api.modrinth.com/v2/project/${id}/version${q}`, {
213	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
214	        });
215	        if (!res.ok) return null;
216	        const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
217	        const v = versions[0];
218	        if (!v) return null;
219	        return (v.files.find((f) => f.primary) ?? v.files[0])?.url ?? null;
220	      }
221	      case "thunderstore": {
222	        const [author, ...rest] = id.split("-");
223	        if (!rest.length) return null;
224	        const res = await fetch(`https://thunderstore.io/api/experimental/package/${author}/${rest.join("-")}/`, {
225	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
226	        });
227	        if (!res.ok) return null;
228	        const pkg = (await res.json()) as { latest?: { download_url?: string } };
229	        return pkg.latest?.download_url ?? null;
230	      }
231	      default:
232	        return null;
233	    }
234	  } catch (e) {
235	    console.error(`[game-mods] resolveUrl(${mod.source}/${id}) failed`, e);
236	    return null;
237	  }
238	}
239	
240	function modrinthLoader(mod: ModRowFull): string | null {
241	  // Prefer the mod's own loader target; fall back to the server's variant.
242	  const key = mod.appliesTo ?? mod.variant ?? "";
243	  const map: Record<string, string> = {
244	    paper: "paper", spigot: "spigot", purpur: "purpur", bukkit: "bukkit",
245	    fabric: "fabric", forge: "forge", neoforge: "neoforge", quilt: "quilt",
246	  };
247	  return map[key] ?? null;
248	}
249	
250	/** Shell snippet that echoes (creating if needed) the mod/plugin dir for family+variant. */
251	/* The shared set in lib/mod-install-support.ts is what the PANEL uses to decide
252	   whether to draw an Install button at all. If this switch ever grows a case
253	   that isn't in that set the button never appears, and if the set grows a
254	   family this switch doesn't handle the button appears and fails — which is the
255	   bug that module was written to end. Fail loudly here rather than let them
256	   drift apart silently. */
257	function modDirShell(family: string, variant: string | null): string | null {
258	  if (!INSTALLABLE_FAMILIES.has(family)) return null;
259	  switch (family) {
260	    case "minecraft": {
261	      const modded = variant && ["fabric", "forge", "neoforge", "quilt"].includes(variant);
262	      const sub = modded ? "mods" : "plugins";
263	      return `root=$(find /opt /srv /home /root -maxdepth 6 -name server.properties -printf '%h\\n' 2>/dev/null | head -1); [ -n "$root" ] && { mkdir -p "$root/${sub}"; echo "$root/${sub}"; }`;
264	    }
265	    case "rust":
