/**
 * Seed the GameMod catalog — the mod/plugin database customers browse and one-click
 * install onto their game servers.
 *
 * Run:  npx tsx prisma/seed-gamemods.ts    (idempotent — upserts on [gameFamily, slug])
 *
 * Scope: the games provisionable today (minecraft, rust, cs2, valheim, palworld).
 * The 14 new games' catalogs (already researched) get appended here as each game's
 * provisioning goes live. Client-side-only Minecraft mods (Sodium, Iris, JEI, …) are
 * intentionally excluded — they can't run on a server.
 *
 * Data verified 2026-08 against Modrinth/SpigotMC/CurseForge, umod.org, GitHub,
 * Thunderstore and Nexus. `sourceId` is the one-click key per source; `url` is
 * derived when omitted.
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

type Seed = {
  name: string;
  slug: string;
  category: string;
  source: string;
  sourceId?: string;
  url?: string;
  modStringId?: string;
  appliesToVariant?: string;
  description: string;
  popularity: number;
  paid?: boolean;
  featured?: boolean;
};

/** Best-effort canonical URL from source + id (explicit `url` always wins). */
function urlFor(family: string, s: Seed): string | null {
  if (s.url) return s.url;
  const id = s.sourceId;
  if (!id) return null;
  switch (s.source) {
    case "modrinth": return `https://modrinth.com/project/${id}`;
    case "spigotmc": return `https://www.spigotmc.org/resources/${id}`;
    case "hangar": return `https://hangar.papermc.io/${id}`;
    case "curseforge": return `https://www.curseforge.com/projects/${id}`;
    case "steam_workshop": return `https://steamcommunity.com/sharedfiles/filedetails/?id=${id}`;
